package theme

import (
	"encoding/json"
	"errors"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// FromJSON parses a JSON string and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.5
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.5
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var raw map[string]interface{}
	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&raw); err != nil {
		return DefaultTheme(), err
	}

	theme := &jsonTheme{
		colors:      make(map[fyne.ThemeColorName]color.Color),
		darkColors:  make(map[fyne.ThemeColorName]color.Color),
		lightColors: make(map[fyne.ThemeColorName]color.Color),
		sizes:       make(map[string]float32),
		fonts:       make(map[string]fyne.Resource),
		icons:       make(map[fyne.ThemeIconName]fyne.Resource),
	}

	// Parse generic colors
	if colors, ok := raw["Colors"].(map[string]interface{}); ok {
		for name, val := range colors {
			if hexStr, ok := val.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					theme.colors[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse dark variant colors
	if colors, ok := raw["Colors-dark"].(map[string]interface{}); ok {
		for name, val := range colors {
			if hexStr, ok := val.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					theme.darkColors[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse light variant colors
	if colors, ok := raw["Colors-light"].(map[string]interface{}); ok {
		for name, val := range colors {
			if hexStr, ok := val.(string); ok {
				if c, err := parseHexColor(hexStr); err == nil {
					theme.lightColors[fyne.ThemeColorName(name)] = c
				}
			}
		}
	}

	// Parse sizes
	if sizes, ok := raw["Sizes"].(map[string]interface{}); ok {
		for name, val := range sizes {
			if floatVal, ok := val.(float64); ok {
				theme.sizes[name] = float32(floatVal)
			}
		}
	}

	// Parse fonts
	if fonts, ok := raw["Fonts"].(map[string]interface{}); ok {
		for style, val := range fonts {
			if uriStr, ok := val.(string); ok {
				if uri, err := storage.ParseURI(uriStr); err == nil {
					if res, err := storage.LoadResourceFromURI(uri); err == nil {
						theme.fonts[style] = res
					}
				}
			}
		}
	}

	// Parse icons
	if icons, ok := raw["Icons"].(map[string]interface{}); ok {
		for name, val := range icons {
			if uriStr, ok := val.(string); ok {
				if uri, err := storage.ParseURI(uriStr); err == nil {
					if res, err := storage.LoadResourceFromURI(uri); err == nil {
						theme.icons[fyne.ThemeIconName(name)] = res
					}
				}
			}
		}
	}

	return theme, nil
}

// parseHexColor parses a hex color string and returns a color.Color.
// Supports formats: 3-digit (#rgb), 4-digit (#rgba), 6-digit (#rrggbb), 8-digit (#rrggbbaa)
// The # prefix is optional.
func parseHexColor(hex string) (color.Color, error) {
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint8
	a = 0xff // default alpha

	switch len(hex) {
	case 3: // rgb
		vals, err := parseHexDigits(hex, 1)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0] | (vals[0] << 4)
		g = vals[1] | (vals[1] << 4)
		b = vals[2] | (vals[2] << 4)
	case 4: // rgba
		vals, err := parseHexDigits(hex, 1)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0] | (vals[0] << 4)
		g = vals[1] | (vals[1] << 4)
		b = vals[2] | (vals[2] << 4)
		a = vals[3] | (vals[3] << 4)
	case 6: // rrggbb
		vals, err := parseHexDigits(hex, 2)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0]
		g = vals[1]
		b = vals[2]
	case 8: // rrggbbaa
		vals, err := parseHexDigits(hex, 2)
		if err != nil {
			return color.Transparent, err
		}
		r = vals[0]
		g = vals[1]
		b = vals[2]
		a = vals[3]
	default:
		return color.Transparent, errors.New("invalid hex color format")
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// parseHexDigits parses hex string into byte values with specified digit width (1 or 2)
func parseHexDigits(hex string, width int) ([]uint8, error) {
	count := len(hex) / width
	result := make([]uint8, count)

	for i := 0; i < count; i++ {
		start := i * width
		end := start + width
		val, err := strconv.ParseUint(hex[start:end], 16, 8)
		if err != nil {
			return nil, err
		}
		result[i] = uint8(val)
	}

	return result, nil
}

type jsonTheme struct {
	colors      map[fyne.ThemeColorName]color.Color
	darkColors  map[fyne.ThemeColorName]color.Color
	lightColors map[fyne.ThemeColorName]color.Color
	sizes       map[string]float32
	fonts       map[string]fyne.Resource
	icons       map[fyne.ThemeIconName]fyne.Resource
}

func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Check variant-specific colors first
	if variant == fyne.ThemeVariantDark {
		if c, ok := t.darkColors[name]; ok {
			return c
		}
	} else if variant == fyne.ThemeVariantLight {
		if c, ok := t.lightColors[name]; ok {
			return c
		}
	}

	// Check generic colors
	if c, ok := t.colors[name]; ok {
		return c
	}

	// Fall back to default theme
	return DefaultTheme().Color(name, variant)
}

func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	var key string
	if style.Monospace {
		key = "monospace"
	} else if style.Bold && style.Italic {
		key = "boldItalic"
	} else if style.Bold {
		key = "bold"
	} else if style.Italic {
		key = "italic"
	} else {
		key = "regular"
	}

	if res, ok := t.fonts[key]; ok {
		return res
	}

	// Fall back to default theme
	return DefaultTheme().Font(style)
}

func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if res, ok := t.icons[name]; ok {
		return res
	}

	// Fall back to default theme
	return DefaultTheme().Icon(name)
}

func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if size, ok := t.sizes[string(name)]; ok {
		return size
	}

	// Fall back to default theme
	return DefaultTheme().Size(name)
}

