// NewSprintf creates a new String binding that formats the source String binding using the given format.
// When the source binding changes, the formatted binding will be updated automatically.
//
// Since: 2.5
func NewSprintf(format string, source String) String {
	result := &formattedString{
		format: format,
		source: source,
		value:  "",
	}

	// Update initially
	result.update()

	// Listen for source changes
	source.AddListener(result)

	return result
}

// StringToStringWithFormat creates a new String binding that applies a custom formatting function
// to transform the source String binding. The formatter receives the source value and returns
// the formatted string. When the source changes, the formatted result is updated automatically.
//
// Since: 2.5
func StringToStringWithFormat(source String, formatter func(string) string) String {
	result := &customFormattedString{
		formatter: formatter,
		source:    source,
		value:     "",
	}

	// Update initially
	result.update()

	// Listen for source changes
	source.AddListener(result)

	return result
}

type formattedString struct {
	base

	format string
	source String
	value  string
}

func (f *formattedString) Get() (string, error) {
	f.lock.RLock()
	defer f.lock.RUnlock()

	return f.value, nil
}

func (f *formattedString) Set(string) error {
	// Formatted bindings are read-only
	return nil
}

func (f *formattedString) DataChanged() {
	f.update()
}

func (f *formattedString) update() {
	val, err := f.source.Get()
	if err != nil {
		return
	}

	newVal := fmt.Sprintf(f.format, val)

	f.lock.Lock()
	if f.value != newVal {
		f.value = newVal
		f.lock.Unlock()
		f.trigger()
	} else {
		f.lock.Unlock()
	}
}

