package binding

import (
	"fmt"
)

// NewSprintf creates a new String binding that formats multiple DataItem bindings using the given format string.
// It accepts a format string and variadic DataItem arguments (which may be Bool, Bytes, Float, Int, Rune, String, or URI bindings).
// When any of the source bindings change, the formatted binding will be updated automatically.
//
// Since: 2.5
func NewSprintf(format string, bindings ...DataItem) String {
	if len(bindings) == 0 {
		return NewString()
	}

	result := &sprintfString{
		format:   format,
		bindings: bindings,
		value:    "",
	}

	// Update initially
	result.update()

	// Listen for changes on all bindings
	for _, b := range bindings {
		b.AddListener(result)
	}

	return result
}

// StringToStringWithFormat creates a new String binding that applies a format string to transform
// the source String binding. If the format is "%s" (identity), it returns the original binding directly (no wrapping).
// Otherwise, it delegates to NewSprintf(format, str).
//
// Since: 2.5
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		// Identity case - return original binding directly
		return str
	}
	// Delegate to NewSprintf
	return NewSprintf(format, str)
}

type sprintfString struct {
	base

	format   string
	bindings []DataItem
	value    string
}

func (s *sprintfString) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	return s.value, nil
}

func (s *sprintfString) Set(string) error {
	// Formatted bindings are read-only
	return nil
}

func (s *sprintfString) DataChanged() {
	s.update()
}

func (s *sprintfString) update() {
	// Extract values from all bindings
	values := make([]interface{}, len(s.bindings))
	for i, binding := range s.bindings {
		var val interface{}
		var err error

		// Type switch to get the appropriate value
		switch b := binding.(type) {
		case String:
			val, err = b.Get()
		case Bool:
			val, err = b.Get()
		case Int:
			val, err = b.Get()
		case Float:
			val, err = b.Get()
		case Rune:
			val, err = b.Get()
		case URI:
			val, err = b.Get()
		default:
			// For other types, try to get as generic DataItem
			continue
		}

		if err != nil {
			return
		}
		values[i] = val
	}

	newVal := fmt.Sprintf(s.format, values...)

	s.lock.Lock()
	if s.value != newVal {
		s.value = newVal
		s.lock.Unlock()
		s.trigger()
	} else {
		s.lock.Unlock()
	}
}

