// NewAllStrings creates a validator that runs all provided validators in order.
// It returns a StringValidator that executes each validator sequentially and returns
// the first error encountered. If all validators pass, it returns nil.
//
// Since: 2.5
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	if len(validators) == 0 {
		// No validators means always valid
		return func(string) error {
			return nil
		}
	}

	return func(text string) error {
		for _, validator := range validators {
			if validator == nil {
				continue
			}
			if err := validator(text); err != nil {
				return err
			}
		}
		return nil
	}
}

