package binding

import (
	"errors"
	"fmt"

	"fyne.io/fyne/v2/storage"
)

func (s *sprintfString) Set(str string) error {
	// Check for Bytes bindings - they cannot be round-tripped
	for _, binding := range s.bindings {
		if _, ok := binding.(Bytes); ok {
			return errors.New("cannot set sprintf binding containing Bytes: Bytes cannot be round-tripped")
		}
	}

	// Create pointers to hold parsed values
	values := make([]interface{}, len(s.bindings))
	for i, binding := range s.bindings {
		switch binding.(type) {
		case Bool:
			var v bool
			values[i] = &v
		case Int:
			var v int
			values[i] = &v
		case Float:
			var v float64
			values[i] = &v
		case Rune:
			var v rune
			values[i] = &v
		case String:
			var v string
			values[i] = &v
		case URI:
			// URI needs special handling - we'll parse it separately
			var v string
			values[i] = &v
		default:
			return errors.New("unsupported binding type in sprintf")
		}
	}

	// Parse the string using Sscanf
	n, err := fmt.Sscanf(str, s.format, values...)
	if err != nil {
		return fmt.Errorf("failed to parse string: %w", err)
	}
	if n != len(s.bindings) {
		return fmt.Errorf("parsed %d values but expected %d", n, len(s.bindings))
	}

	// Set the parsed values back to the bindings
	for i, binding := range s.bindings {
		switch b := binding.(type) {
		case Bool:
			if err := b.Set(*values[i].(*bool)); err != nil {
				return err
			}
		case Int:
			if err := b.Set(*values[i].(*int)); err != nil {
				return err
			}
		case Float:
			if err := b.Set(*values[i].(*float64)); err != nil {
				return err
			}
		case Rune:
			if err := b.Set(*values[i].(*rune)); err != nil {
				return err
			}
		case String:
			if err := b.Set(*values[i].(*string)); err != nil {
				return err
			}
		case URI:
			// Parse URI using storage.ParseURI
			uriStr := *values[i].(*string)
			uri, err := storage.ParseURI(uriStr)
			if err != nil {
				return fmt.Errorf("failed to parse URI: %w", err)
			}
			if err := b.Set(uri); err != nil {
				return err
			}
		}
	}

	return nil
}

